import os

DEFAULTS = {
    "PAYHOOK_API_TOKEN": None,
    "PAYHOOK_WEBHOOK_SECRET": None,
    "PAYHOOK_ENDPOINT": "https://api.payments.example/v1",
    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be printed in full (e.g. by `doctor`).
SECRET_KEYS = frozenset({"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"})


def _parse_value(raw):
    value = raw.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    return value


def _parse_line(line):
    """Return (key, value) for an assignment line, or None to skip it."""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export ") or line.startswith("export\t"):
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, raw_value = line.split("=", 1)
    key = key.strip()
    if not key:
        return None
    return key, _parse_value(raw_value)


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = _parse_line(line)
            if parsed is not None:
                key, value = parsed
                values[key] = value
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config

