import os
import sys

from .config import DEFAULTS, SECRET_KEYS, load_config

DOTENV_PATH = ".env"


def _check(config):
    missing = [k for k, (v, _) in config.items() if v is None]
    print("missing: " + ", ".join(missing) if missing else "ok")
    return 1 if missing else 0


def _display_value(key, value):
    if value is None:
        return "<not set>"
    if key in SECRET_KEYS:
        # Secrets are never printed; the length is enough to tell if one was loaded.
        return f"<redacted, {len(value)} chars>"
    return repr(value)


def _doctor(config):
    dotenv_state = "found" if os.path.exists(DOTENV_PATH) else "not found"
    print("payhook configuration")
    print(f"dotenv file: {os.path.abspath(DOTENV_PATH)} ({dotenv_state})")
    print("sources: environment > .env > default")
    print()
    for key in DEFAULTS:
        value, source = config[key]
        print(f"{key} = {_display_value(key, value)}")
        print(f"    source: {source}")
    return 0


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv == ["check"]:
        return _check(load_config(dotenv_path=DOTENV_PATH))
    if argv == ["doctor"]:
        return _doctor(load_config(dotenv_path=DOTENV_PATH))
    print("usage: python -m payhook {check|doctor}", file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main())

